create table sales.customer_payment (tenant_id uuid not null references core.tenant(id), id uuid not null, number bigint generated always as identity, customer_id uuid not null, payment_date date not null, amount numeric(18,2) not null check (amount > 0), method text not null check (method in ('Cash','Bank','UPI')), reference text null check (reference is null or length(reference) <= 60), idempotency_key text not null check (length(idempotency_key) between 8 and 100), request_hash text not null, journal_entry_id uuid not null, created_by uuid not null, created_at timestamptz not null default now(), primary key (tenant_id, id), unique (tenant_id, idempotency_key), foreign key (tenant_id, customer_id) references sales.customer(tenant_id, id), foreign key (tenant_id, journal_entry_id) references accounting.journal_entry(tenant_id, id));
create table sales.sale_return (tenant_id uuid not null references core.tenant(id), id uuid not null, number bigint generated always as identity, sale_id uuid not null, customer_id uuid null, return_date date not null, reason text null check (reason is null or length(reason) <= 200), total numeric(18,2) not null check (total > 0), receivable_credit numeric(18,2) not null check (receivable_credit >= 0), cash_refund numeric(18,2) not null check (cash_refund >= 0), idempotency_key text not null check (length(idempotency_key) between 8 and 100), request_hash text not null, journal_entry_id uuid not null, created_by uuid not null, created_at timestamptz not null default now(), primary key (tenant_id, id), unique (tenant_id, idempotency_key), check (receivable_credit + cash_refund = total), foreign key (tenant_id, sale_id) references sales.sale(tenant_id, id), foreign key (tenant_id, customer_id) references sales.customer(tenant_id, id), foreign key (tenant_id, journal_entry_id) references accounting.journal_entry(tenant_id, id));
create table sales.sale_return_line (tenant_id uuid not null, return_id uuid not null, sale_id uuid not null, product_id uuid not null, quantity numeric(18,3) not null check (quantity > 0), amount numeric(18,2) not null check (amount >= 0), unit_cost numeric(18,4) not null check (unit_cost >= 0), primary key (tenant_id, return_id, product_id), foreign key (tenant_id, return_id) references sales.sale_return(tenant_id, id), foreign key (tenant_id, product_id) references catalog.product(tenant_id, id));
create index sale_return_line_sale_ix on sales.sale_return_line (tenant_id, sale_id, product_id);
create table procurement.purchase_return (tenant_id uuid not null references core.tenant(id), id uuid not null, number bigint generated always as identity, receipt_id uuid not null, supplier_id uuid not null, location_id uuid not null, return_date date not null, reason text null check (reason is null or length(reason) <= 200), total numeric(18,2) not null check (total > 0), idempotency_key text not null check (length(idempotency_key) between 8 and 100), request_hash text not null, journal_entry_id uuid not null, created_by uuid not null, created_at timestamptz not null default now(), primary key (tenant_id, id), unique (tenant_id, idempotency_key), foreign key (tenant_id, receipt_id) references procurement.purchase_receipt(tenant_id, id), foreign key (tenant_id, supplier_id) references procurement.supplier(tenant_id, id), foreign key (tenant_id, location_id) references core.stock_location(tenant_id, id), foreign key (tenant_id, journal_entry_id) references accounting.journal_entry(tenant_id, id));
create table procurement.purchase_return_line (tenant_id uuid not null, return_id uuid not null, receipt_id uuid not null, product_id uuid not null, quantity numeric(18,3) not null check (quantity > 0), unit_cost numeric(18,4) not null check (unit_cost > 0), amount numeric(18,2) not null check (amount >= 0), primary key (tenant_id, return_id, product_id), foreign key (tenant_id, return_id) references procurement.purchase_return(tenant_id, id), foreign key (tenant_id, product_id) references catalog.product(tenant_id, id));
create index purchase_return_line_receipt_ix on procurement.purchase_return_line (tenant_id, receipt_id, product_id);
do $$ declare t text; begin foreach t in array array['sales.customer_payment','sales.sale_return','sales.sale_return_line','procurement.purchase_return','procurement.purchase_return_line'] loop execute format('alter table %s enable row level security', t); execute format('alter table %s force row level security', t); execute format('create policy tenant_isolation on %s for all to rbos_app using (tenant_id = core.current_tenant_id() and core.is_active_member(tenant_id)) with check (tenant_id = core.current_tenant_id() and core.is_active_member(tenant_id))', t); end loop; end $$;
grant select, insert on sales.customer_payment, sales.sale_return, sales.sale_return_line, procurement.purchase_return, procurement.purchase_return_line to rbos_app;
